#include "game/GameBootstrap.h"
#include "content/ContentCatalog.h"
#include "content/resources/ResourcePack.h"
#include "client/render/ModelBakery.h"
#include <iostream>
#include <set>
int main(){try{mc::game::GameBootstrap b("assets");b.loadContentModules();b.freezeRegistries();const auto& c=b.content();const mc::content::resources::ResourcePack r("assets");const mc::client::ModelBakery bakery(r,c);std::set<std::string> fail;std::size_t models=0;for(const auto& n:r.itemModelNames()){++models;if(!c.item(n))fail.insert("unregistered item model: "+n.toString());}for(const auto& e:c.items().entries()){const auto t=c.itemType(e.name);if(!t){fail.insert("no runtime ItemStack id: "+e.name.toString());continue;}const auto* rt=c.itemName(*t);if(!rt||*rt!=e.name)fail.insert("item id roundtrip failed: "+e.name.toString());bool visual=false;if(e.value.model)try{const auto baked=bakery.bakeModel(*e.value.model);visual=!baked.quads.empty();auto cur=*e.value.model;for(int d=0;!visual&&d<32;++d){if(cur.path().rfind("builtin/",0)==0)break;const auto raw=r.loadModel(cur);if(raw.textures.contains("layer0"))visual=true;if(!raw.parent)break;cur=*raw.parent;}}catch(const std::exception& x){fail.insert("model failure: "+e.name.toString()+" :: "+x.what());}if(e.value.placedBlock){if(c.itemBlockState(*t,0))visual=true;else fail.insert("invalid ItemBlock state: "+e.name.toString());}if(!visual)fail.insert("NO REAL VISUAL / unsupported builtin: "+e.name.toString());}std::cout<<"Blocks: "<<c.blocks().size()<<'\n'<<"Runtime items: "<<c.items().size()<<'\n'<<"Vanilla item models: "<<models<<'\n';if(!fail.empty()){std::cerr<<"Stage 5 unresolved cases ("<<fail.size()<<"):\n";for(const auto& x:fail)std::cerr<<"  "<<x<<'\n';return 1;}std::cout<<"PASS: all registered 1.12.2 block/item resources have runtime identity and real visuals.\n";return 0;}catch(const std::exception& x){std::cerr<<"Stage 5 audit failed: "<<x.what()<<'\n';return 2;}}
